<?php
require_once 'config.php'; require_login();
$userId=(int)$_SESSION['user_id'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??''; $itemId=(int)($_POST['item_id']??0);
    if ($action==='remove') { $s=$conn->prepare("DELETE FROM cart_items WHERE id=? AND user_id=?"); $s->bind_param('ii',$itemId,$userId); $s->execute(); }
    if ($action==='update') { $qty=max(1,min(20,(int)($_POST['quantity']??1))); $s=$conn->prepare("UPDATE cart_items ci JOIN products p ON p.id=ci.product_id SET ci.quantity=LEAST(?,p.stock), ci.updated_at=NOW() WHERE ci.id=? AND ci.user_id=?"); $s->bind_param('iii',$qty,$itemId,$userId); $s->execute(); }
    header('Location: cart.php'); exit;
}
$items=[]; $stmt=$conn->prepare("SELECT ci.id item_id, ci.quantity, p.id product_id, p.name, p.price, p.image, p.stock FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=? ORDER BY ci.created_at DESC"); $stmt->bind_param('i',$userId); $stmt->execute(); $res=$stmt->get_result(); while($r=$res->fetch_assoc()){$items[]=$r;} $stmt->close();
$total=0; foreach($items as &$i){$i['line_total']=(float)$i['price']*(int)$i['quantity'];$total+=$i['line_total'];} unset($i);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart - Style Hub</title><link rel="stylesheet" href="style.css"></head><body>
<header><a class="logo" href="home.php">Style Hub</a><nav><a href="home.php">Home</a><a href="category.php?cat=Men">Men</a><a href="category.php?cat=Women">Women</a><a href="category.php?cat=Kids">Kids</a><a href="category.php?cat=Accessories">Accessories</a></nav><div class="header-right"><span class="welcome">Hi, <?=htmlspecialchars($_SESSION['user_name'])?></span><a class="auth-btn" href="logout.php">Logout</a></div></header>
<main class="section"><h2>Your Shopping Cart</h2><?php if(!$items):?><div class="notice"><h3>Your cart is empty.</h3><p>Explore our fashion collection and add something you love.</p><a class="primary-btn" href="home.php#products">Continue Shopping</a></div><?php else:?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $item):?><article class="cart-card"><img src="<?=htmlspecialchars($item['image'])?>" alt=""><div class="cart-info"><h3><?=htmlspecialchars($item['name'])?></h3><p class="price">₹<?=number_format($item['price'],2)?></p><form method="post" class="qty-form"><input type="hidden" name="action" value="update"><input type="hidden" name="item_id" value="<?=$item['item_id']?>"><input type="number" name="quantity" min="1" max="<?=$item['stock']?>" value="<?=$item['quantity']?>"><button class="small-btn">Update</button></form><form method="post"><input type="hidden" name="action" value="remove"><input type="hidden" name="item_id" value="<?=$item['item_id']?>"><button class="link-btn">Remove</button></form></div><strong>₹<?=number_format($item['line_total'],2)?></strong></article><?php endforeach;?></div><aside class="summary-card"><h3>Order Summary</h3><div class="summary-row"><span>Subtotal</span><b>₹<?=number_format($total,2)?></b></div><div class="summary-row"><span>Delivery</span><b>FREE</b></div><hr><div class="summary-row total"><span>Total</span><b>₹<?=number_format($total,2)?></b></div><a class="primary-btn full" href="checkout.php">Proceed to Checkout</a></aside></div><?php endif;?></main></body></html>
